    await servidor.stop();
    process.exit(0);
  };
  process.on("SIGINT", parar);
  process.on("SIGTERM", parar);
  setInterval(() => {}, 1 << 30);
}

main().catch((erro) => {
  console.error(erro);
  process.exit(1);
});
