import { Marca } from "@/components/Marca";
import { Aviso } from "@/components/ui";
import { obterSessao } from "@/server/auth/sessao";
import { FormEntrar } from "./FormEntrar";

export const metadata: Metadata = { title: "Entrar" };

const MENSAGENS: Record<string, { tom: "info" | "warn"; texto: string }> = {
  inatividade: { tom: "info", texto: "Sua sessão foi encerrada após um período sem uso. Entre novamente para continuar." },
  duracao_maxima: { tom: "info", texto: "Por segurança, sessões têm duração máxima. Entre novamente para continuar." },
  encerrada: { tom: "info", texto: "Você saiu da sua conta." },
  senha_redefinida: { tom: "info", texto: "Senha alterada. Entre com a nova senha." },
  ativada: { tom: "info", texto: "Conta ativada. Entre para ver suas orientações." },
};

export default async function Page(props: PageProps<"/entrar">) {
  const sessao = await obterSessao();
  if (!("motivo" in sessao)) redirect("/inicio");

  const { motivo } = await props.searchParams;
  const mensagem = typeof motivo === "string" ? MENSAGENS[motivo] : undefined;

  return (
    <div className="flex flex-1 flex-col">
      <header className="mx-auto w-full max-w-6xl px-4 pt-6">
        <Marca />
      </header>

      <main className="mx-auto grid w-full max-w-6xl flex-1 items-start gap-10 px-4 py-8 lg:grid-cols-[minmax(0,28rem)_1fr] lg:py-14">
        <section aria-labelledby="titulo-entrar">
          <h1 id="titulo-entrar" className="text-3xl font-extrabold">
            Entrar
          </h1>
          <p className="mt-2 text-muted">Acesse suas orientações de alta ou a área da equipe.</p>

          {mensagem && (
            <div className="mt-5">
              <Aviso tom={mensagem.tom}>{mensagem.texto}</Aviso>
            </div>
          )}

          <div className="mt-6">
            <FormEntrar />
          </div>

          <div className="mt-8 space-y-2 border-t border-line pt-6 text-muted">
            <p>
              <strong className="text-ink">Primeiro acesso?</strong> Use o QR code que a equipe entregou na sua alta.
              Ele leva à ativação da conta.
            </p>
            <p>
              <Link href="/demo" className="font-semibold text-primary underline underline-offset-4">
                Ver a demonstração sem entrar
              </Link>{" "}
              (paciente fictício, sem conta).
            </p>
          </div>
        </section>

        <aside className="hidden lg:block" aria-label="Sobre o Alta Clara">
          <IlustracaoTransicao />
          <div className="mt-6 grid grid-cols-3 gap-4 text-sm">
            <Destaque titulo="O que fazer hoje" texto="Remédios na hora certa, com a próxima ação em destaque." />
            <Destaque titulo="Revisado pela equipe" texto="Cada orientação mostra a versão, a data e quem revisou." />
            <Destaque titulo="Quando procurar ajuda" texto="Contatos e orientações de urgência sempre visíveis." />
          </div>
        </aside>
      </main>
    </div>
  );
}

function Destaque({ titulo, texto }: { titulo: string; texto: string }) {
  return (
    <div className="rounded-2xl border border-line bg-surface p-4">
      <p className="font-bold">{titulo}</p>
      <p className="mt-1 text-muted">{texto}</p>
    </div>
