}

export function Campo({
  id,
  rotulo,
  dica,
  erro,
  acessorio,
  ...props
}: InputHTMLAttributes<HTMLInputElement> & {
  id: string;
  rotulo: string;
  dica?: string;
  erro?: string | null;
