export function Aviso({ tom = "info", titulo, children }: { tom?: "info" | "warn" | "danger"; titulo?: string; children: ReactNode }) {
  const cores = { info: "bg-info-soft text-info", warn: "bg-warn-soft text-warn", danger: "bg-danger-soft text-danger" }[tom];
  return (
    <div role={tom === "danger" ? "alert" : "status"} className={`rounded-xl p-4 ${cores}`}>
      {titulo && <p className="font-bold">{titulo}</p>}
      <div className="text-ink">{children}</div>
    </div>
  );
