@import "tailwindcss";

/* Identidade Alta Clara: branco quente, azul profundo e verde-petróleo.
   Contraste de cada par verificado por scripts/contraste.ts (WCAG AA).
   Cores de alerta (contato, urgência) são reservadas a estados clínicos
   definidos pela equipe; o grupo "previsto" usa azul informativo, não verde. */
:root {
  --bg: #f4f8fa;
  --surface: #ffffff;
  --ink: #12304a;
  --muted: #4a6072;
  --line: #d5e1e8;
  --primary: #006b68;
  --primary-ink: #ffffff;
  --primary-soft: #ddefea;
  --info: #1d4f7a;
  --info-soft: #e3eef7;
  --warn: #7a4b00;
  --warn-soft: #fff1d6;
  --danger: #a8221a;
  --danger-soft: #fde8e6;
  --focus: #1d4ed8;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0e1a24;
    --surface: #152532;
    --ink: #e8eef3;
    --muted: #a9b8c4;
    --line: #26394a;
    --primary: #5fc7bf;
    --primary-ink: #06302e;
    --primary-soft: #133533;
    --info: #9cc6ec;
    --info-soft: #14283a;
    --warn: #f3c163;
    --warn-soft: #3a2b0b;
    --danger: #ff9a90;
    --danger-soft: #3d1614;
    --focus: #93b4ff;
  }
}

@theme inline {
  --color-bg: var(--bg);
  --color-surface: var(--surface);
  --color-ink: var(--ink);
  --color-muted: var(--muted);
  --color-line: var(--line);
  --color-primary: var(--primary);
  --color-primary-ink: var(--primary-ink);
  --color-primary-soft: var(--primary-soft);
  --color-info: var(--info);
  --color-info-soft: var(--info-soft);
  --color-warn: var(--warn);
  --color-warn-soft: var(--warn-soft);
  --color-danger: var(--danger);
  --color-danger-soft: var(--danger-soft);
  --font-sans: var(--font-atkinson);
}

html {
  /* Base de 18px: o público principal lê melhor com letra maior. */
  font-size: 112.5%;
  scroll-behavior: smooth;
  scroll-padding-top: 5rem;
}

/* Fonte ampliada, escolhida pelo paciente (preferência salva no aparelho). */
html[data-fonte="grande"] {
  font-size: 131.25%;
}

body {
  background: var(--bg);
  color: var(--ink);
}

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 6px;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
  }
}

@media print {
  .no-print {
    display: none !important;
  }
  html {
    font-size: 12pt;
  }
  body {
    background: #fff;
    color: #000;
  }
}

import type { Metadata, Viewport } from "next";
import { Atkinson_Hyperlegible_Next } from "next/font/google";
import { headers } from "next/headers";
import "./globals.css";

// Fonte criada pelo Braille Institute para leitores com baixa visão.
const atkinson = Atkinson_Hyperlegible_Next({
  variable: "--font-atkinson",
  subsets: ["latin", "latin-ext"],
  // O Next ainda não tem métricas desta fonte para gerar o fallback ajustado.
  adjustFontFallback: false,
});

export const metadata: Metadata = {
  title: { default: "Alta Clara", template: "%s · Alta Clara" },
  description: "Seu cuidado continua em casa. Orientações de alta claras, revisadas pela equipe.",
};

export const viewport: Viewport = {
  themeColor: [
    { media: "(prefers-color-scheme: light)", color: "#f4f8fa" },
    { media: "(prefers-color-scheme: dark)", color: "#0e1a24" },
  ],
};

export default async function RootLayout({ children }: LayoutProps<"/">) {
  // Renderização dinâmica: cada resposta recebe o nonce da CSP (src/proxy.ts).
  await headers();

  return (
    <html lang="pt-BR" className={`${atkinson.variable} h-full antialiased`}>
      <body className="flex min-h-full flex-col font-sans">
