const urlBase = process.env.BETTER_AUTH_URL ?? "http://localhost:3100";
const producao = process.env.NODE_ENV === "production";

// Operações que cadastram ou removem autenticadores exigem login recente,
// para que uma sessão esquecida aberta não sirva de atalho para contornar o MFA.
const EXIGEM_LOGIN_RECENTE = new Set([
  "/passkey/generate-register-options",
  "/passkey/delete-passkey",
  "/two-factor/generate-backup-codes",
  "/two-factor/disable",
]);
const LOGIN_RECENTE_MS = 10 * 60 * 1000;

export const auth = betterAuth({
  appName: "Alta Clara",
  baseURL: urlBase,
  secret: process.env.BETTER_AUTH_SECRET,
  trustedOrigins: [urlBase],
  database: drizzleAdapter(db, { provider: "pg", schema, usePlural: false }),
  // Nenhum dado de uso é enviado ao fornecedor da biblioteca.
  telemetry: { enabled: false },

  emailAndPassword: {
    enabled: true,
    // Contas só são criadas por convite (paciente/cuidador) ou provisionamento
    // institucional (profissionais). Não existe cadastro aberto.
    disableSignUp: true,
    minPasswordLength: SENHA_MIN,
    maxPasswordLength: SENHA_MAX,
    password: { hash: hashSenha, verify: verificarSenha },
    revokeSessionsOnPasswordReset: true,
    resetPasswordTokenExpiresIn: 30 * 60,
    async sendResetPassword({ user, url }) {
      await enviarMensagem({
        para: user.email,
        assunto: "Redefinição de senha do Alta Clara",
        corpo: `Recebemos um pedido para redefinir sua senha. O link vale por 30 minutos:\n\n${url}\n\nSe não foi você, ignore esta mensagem. Sua senha atual continua valendo.`,
      });
    },
    async onPasswordReset({ user }) {
      await enviarMensagem({
        para: user.email,
        assunto: "Sua senha do Alta Clara foi alterada",
        corpo: "Sua senha foi alterada e as sessões abertas foram encerradas. Se não foi você, procure a unidade de saúde.",
      });
    },
  },

  session: {
    // Duração absoluta máxima de qualquer sessão. Limites mais curtos por
    // perfil (ex.: 15 min de inatividade e 8 h para profissionais) são
    // aplicados em src/server/auth/sessao.ts.
    expiresIn: 7 * 24 * 60 * 60,
    disableSessionRefresh: true,
    freshAge: 10 * 60,
    additionalFields: {
      ultimaAtividade: { type: "date", required: false, input: false },
    },
  },

  rateLimit: {
    enabled: true,
    storage: "database",
    window: 60,
    max: 100,
    customRules: {
      "/sign-in/email": { window: 60, max: 10 },
      "/two-factor/verify-totp": { window: 60, max: 6 },
      "/two-factor/verify-backup-code": { window: 60, max: 6 },
      "/request-password-reset": { window: 300, max: 3 },
    },
  },

  advanced: {
    useSecureCookies: producao,
    cookiePrefix: "alta",
  },

  hooks: {
    before: createAuthMiddleware(async (ctx) => {
      if (!EXIGEM_LOGIN_RECENTE.has(ctx.path)) return;
      const sessao = await getSessionFromCtx(ctx);
      if (!sessao || Date.now() - new Date(sessao.session.createdAt).getTime() > LOGIN_RECENTE_MS) {
        throw new APIError("FORBIDDEN", { message: "Por segurança, entre novamente antes de alterar seus métodos de acesso." });
      }
    }),
  },

  plugins: [
    twoFactor({
      issuer: "Alta Clara",
      // Códigos de recuperação de uso único, cifrados com o segredo do servidor.
      backupCodeOptions: { amount: 10, storeBackupCodes: "encrypted" },
    }),
    passkey({
      rpID: new URL(urlBase).hostname,
      rpName: "Alta Clara",
      origin: urlBase,
      // Verificação do usuário no autenticador (biometria/PIN no próprio aparelho).
      authenticatorSelection: { residentKey: "preferred", userVerification: "required" },
      registration: {
        async afterVerification({ user: dono }) {
          const [u] = await db.select({ email: schema.user.email }).from(schema.user).where(eq(schema.user.id, dono.id));
          const email = u?.email;
          if (email) {
            await enviarMensagem({
              para: email,
              assunto: "Nova passkey cadastrada no Alta Clara",
              corpo: "Uma nova passkey foi cadastrada na sua conta. Se não foi você, procure a unidade de saúde.",
            });
          }
        },
      },
    }),
    nextCookies(),
  ],
});

export type Auth = typeof auth;

import { auth } from "./auth";
import { hashSenha, problemaNaSenha } from "./senha";

/**
 * Cria uma conta com senha pelo adaptador interno do Better Auth.
 * Usado SOMENTE por fluxos já autorizados no servidor: ativação por convite
 * (depois do código no canal validado) e provisionamento institucional.
 * O cadastro público está desativado (emailAndPassword.disableSignUp).
 */
export async function criarContaComSenha(dados: {
  email: string;
  nome: string;
  senha: string;
}): Promise<{ userId: string } | { erro: string }> {
  const problema = problemaNaSenha(dados.senha, dados.email);
  if (problema) return { erro: problema };

  const ctx = await auth.$context;
  const existente = await ctx.internalAdapter.findUserByEmail(dados.email);
  if (existente) return { erro: "conta_existente" };

  const usuario = await ctx.internalAdapter.createUser({
    email: dados.email.toLowerCase(),
    name: dados.nome,
    emailVerified: true,
  }, { method: "email-password" });
  await ctx.internalAdapter.linkAccount({
    userId: usuario.id,
    providerId: "credential",
    accountId: usuario.id,
    password: await hashSenha(dados.senha),
  });
  return { userId: usuario.id };
}

// Política de sessão do protótipo (escolha do projeto, a validar no fluxo real;
// ver docs/pesquisa.md — OWASP sugere 15–30 min de inatividade e 4–8 h absolutas).
export const POLITICA_SESSAO = {
  profissional: { inatividadeMin: 15, absolutaHoras: 8 },
  paciente: { inatividadeMin: 60 * 24, absolutaHoras: 24 * 7 },
} as const;

export type MotivoExpiracao = "inatividade" | "duracao_maxima";

/** Função pura: decide se a sessão expirou e quanto tempo resta. */
export function avaliarSessao(e: { criadaEm: Date; ultimaAtividade: Date | null; profissional: boolean; agora: number }) {
  const p = e.profissional ? POLITICA_SESSAO.profissional : POLITICA_SESSAO.paciente;
  const criada = e.criadaEm.getTime();
  const ultima = (e.ultimaAtividade ?? e.criadaEm).getTime();
  const fimAbsoluto = criada + p.absolutaHoras * 3_600_000;
  const fimInatividade = ultima + p.inatividadeMin * 60_000;
  let motivo: MotivoExpiracao | null = null;
  if (e.agora > fimAbsoluto) motivo = "duracao_maxima";
  else if (e.agora > fimInatividade) motivo = "inatividade";
  return { motivo, restanteMs: Math.min(fimAbsoluto, fimInatividade) - e.agora, fimAbsoluto };
}

import { hash, verify } from "@node-rs/argon2";

// Argon2id com os parâmetros mínimos recomendados pela OWASP
// (Password Storage Cheat Sheet): m=19 MiB, t=2, p=1.
const PARAMETROS = { memoryCost: 19_456, timeCost: 2, parallelism: 1, algorithm: 2 /* Argon2id */ } as const;

export const SENHA_MIN = 15; // NIST SP 800-63B-4: 15 quando a senha é fator único.
export const SENHA_MAX = 128;

export function hashSenha(senha: string): Promise<string> {
  return hash(senha, PARAMETROS);
}

export async function verificarSenha({ hash: h, password }: { hash: string; password: string }) {
  try {
    return await verify(h, password);
  } catch {
    return false;
  }
}

// Lista local e pequena de senhas comuns. Em produção, trocar por uma lista
// maior (ex.: top 100 mil de vazamentos) mantida fora do código.
const COMUNS = new Set([
  "123456789012345",
  "1234567890123456",
  "senhasenhasenha",
  "passwordpassword",
  "qwertyuiopasdfgh",
  "aaaaaaaaaaaaaaa",
  "altaclaraaltaclara",
  "minhasenhaforte123",
  "senha12345678910",
]);

/** Mensagem de erro em linguagem simples, ou null se a senha é aceitável. */
export function problemaNaSenha(senha: string, email?: string): string | null {
  if (senha.length < SENHA_MIN) return `Use pelo menos ${SENHA_MIN} caracteres. Uma frase com espaços funciona bem.`;
  if (senha.length > SENHA_MAX) return `Use no máximo ${SENHA_MAX} caracteres.`;
  const normalizada = senha.toLowerCase().replace(/\s+/g, "");
  if (COMUNS.has(normalizada) || /^(.)\1+$/.test(normalizada)) return "Esta senha é muito comum. Escolha outra.";
  if (email && normalizada.includes(email.toLowerCase().split("@")[0])) {
    return "A senha não pode conter o seu e-mail.";
  }
  return null;
}

import "server-only";
import { eq } from "drizzle-orm";
import { headers } from "next/headers";
import { redirect } from "next/navigation";
import { cache } from "react";
import { auditar } from "../auditoria";
import { carregarAtor } from "../authz/ator";
import { ehProfissional, type Ator } from "../authz/politicas";
import { db } from "../db/cliente";
import { session as sessaoTabela } from "../db/schema";
import { auth } from "./auth";
import { avaliarSessao, type MotivoExpiracao } from "./politica-sessao";

export { POLITICA_SESSAO } from "./politica-sessao";

const GRAVAR_ATIVIDADE_A_CADA_MS = 60_000;

export type SessaoAtual = {
  sessaoId: string;
  ator: Ator;
  email: string;
  nome: string;
  /** Instante (ms) em que a sessão expira se não houver atividade, para o aviso. */
  expiraEm: number;
  fimAbsoluto: number;
};

export type MotivoSemSessao = "sem_sessao" | MotivoExpiracao;

/** Valida a sessão no servidor, aplica a política por perfil e devolve o ator. */
export const obterSessao = cache(async (): Promise<SessaoAtual | { motivo: MotivoSemSessao }> => {
  const dados = await auth.api.getSession({ headers: await headers() });
  if (!dados) return { motivo: "sem_sessao" };

  const ator = await carregarAtor(dados.user.id);
  const agora = Date.now();
  const ultimaAtividade = (dados.session as { ultimaAtividade?: Date | null }).ultimaAtividade ?? null;
  const avaliacao = avaliarSessao({
    criadaEm: new Date(dados.session.createdAt),
    ultimaAtividade: ultimaAtividade ? new Date(ultimaAtividade) : null,
    profissional: ehProfissional(ator),
    agora,
  });

  if (avaliacao.motivo) {
    // Revogação efetiva: a sessão é apagada no servidor.
    await db.delete(sessaoTabela).where(eq(sessaoTabela.id, dados.session.id));
    await auditar({ atorUserId: ator.userId, acao: "sessao.expirada", resultado: "permitido", detalhes: { motivo: avaliacao.motivo } });
    return { motivo: avaliacao.motivo };
  }

  const ultima = new Date(ultimaAtividade ?? dados.session.createdAt).getTime();
  const gravar = agora - ultima > GRAVAR_ATIVIDADE_A_CADA_MS;
  if (gravar) {
    await db.update(sessaoTabela).set({ ultimaAtividade: new Date(agora) }).where(eq(sessaoTabela.id, dados.session.id));
  }

  const novaAvaliacao = avaliarSessao({
    criadaEm: new Date(dados.session.createdAt),
    ultimaAtividade: new Date(gravar ? agora : ultima),
    profissional: ehProfissional(ator),
    agora,
  });
  return {
    sessaoId: dados.session.id,
    ator,
    email: dados.user.email,
    nome: dados.user.name,
    expiraEm: agora + novaAvaliacao.restanteMs,
    fimAbsoluto: novaAvaliacao.fimAbsoluto,
  };
});

/** Para páginas: redireciona ao login quando não há sessão válida. */
export async function exigirSessao(): Promise<SessaoAtual> {
  const s = await obterSessao();
  if ("motivo" in s) redirect(s.motivo === "sem_sessao" ? "/entrar" : `/entrar?motivo=${s.motivo}`);
  return s;
}

/** Para a área profissional: exige vínculo ativo e MFA configurado. */
export async function exigirProfissional(): Promise<SessaoAtual> {
  const s = await exigirSessao();
  if (!ehProfissional(s.ator)) redirect("/paciente");
  if (!s.ator.mfaAtivo) redirect("/conta/seguranca?exigir=mfa");
  return s;
}

import { and, eq, gt, isNull, or } from "drizzle-orm";
import { db } from "../db/cliente";
import { autorizacaoCuidador, paciente, user, vinculo } from "../db/schema";
import type { Ator, Papel } from "./politicas";

/** Monta o ator a partir do banco. Nada vem do cliente além do id da sessão. */
export async function carregarAtor(userId: string): Promise<Ator> {
  const [u] = await db.select({ mfa: user.twoFactorEnabled }).from(user).where(eq(user.id, userId));

  const vinculos = await db
    .select({ instituicaoId: vinculo.instituicaoId, papel: vinculo.papel })
    .from(vinculo)
    .where(and(eq(vinculo.userId, userId), eq(vinculo.ativo, true)));

  const proprios = await db.select({ id: paciente.id }).from(paciente).where(eq(paciente.userId, userId));

  const cuidados = await db
    .select({ pacienteId: autorizacaoCuidador.pacienteId, escopo: autorizacaoCuidador.escopo })
    .from(autorizacaoCuidador)
    .where(
      and(
        eq(autorizacaoCuidador.cuidadorUserId, userId),
        isNull(autorizacaoCuidador.revogadoEm),
        or(isNull(autorizacaoCuidador.expiraEm), gt(autorizacaoCuidador.expiraEm, new Date())),
      ),
    );

  return {
    userId,
    mfaAtivo: Boolean(u?.mfa),
    vinculos: vinculos.map((v) => ({ instituicaoId: v.instituicaoId, papel: v.papel as Papel })),
    pacientesProprios: proprios.map((p) => p.id),
    cuidadorDe: cuidados,
  };
}

// Matriz de permissões do Alta Clara. Funções puras: recebem o ator (montado
// no servidor a partir da sessão) e os fatos do recurso (lidos do banco).
// Nada aqui confia em ids, papéis ou instituição enviados pelo cliente.
// Regra geral: negação por padrão — toda função começa em `false`.

export type Papel = "enfermagem" | "revisor" | "admin" | "auditor";

export type Ator = {
  userId: string;
  /** Verdadeiro se a conta exige segundo fator (TOTP) no login. */
  mfaAtivo: boolean;
  vinculos: { instituicaoId: string; papel: Papel }[];
  /** Pacientes cuja conta é deste usuário. */
  pacientesProprios: string[];
  /** Pacientes que autorizaram este usuário como cuidador (ativos). */
  cuidadorDe: { pacienteId: string; escopo: string[] }[];
};

export type FatosPlano = {
  instituicaoId: string;
  pacienteId: string;
  atendimentoId: string;
  status: "rascunho" | "em_revisao" | "publicado" | "substituido" | "encerrado";
  autorId: string;
  /** Profissionais com vínculo assistencial neste atendimento. */
  equipe: string[];
};

export const ESCOPOS_CUIDADOR = ["ver_plano", "registrar_dose"] as const;
export type EscopoCuidador = (typeof ESCOPOS_CUIDADOR)[number];

export function temPapel(ator: Ator, instituicaoId: string, ...papeis: Papel[]): boolean {
  return ator.vinculos.some((v) => v.instituicaoId === instituicaoId && papeis.includes(v.papel));
}

export function ehProfissional(ator: Ator): boolean {
  return ator.vinculos.length > 0;
}

/** Profissionais só operam com MFA ativo. */
function profissionalApto(ator: Ator, instituicaoId: string, ...papeis: Papel[]): boolean {
  return ator.mfaAtivo && temPapel(ator, instituicaoId, ...papeis);
}

const VISIVEL_AO_PACIENTE = new Set<FatosPlano["status"]>(["publicado", "substituido", "encerrado"]);

export function podeVerPlano(ator: Ator, p: FatosPlano): boolean {
  if (VISIVEL_AO_PACIENTE.has(p.status)) {
    if (ator.pacientesProprios.includes(p.pacienteId)) return true;
    if (ator.cuidadorDe.some((c) => c.pacienteId === p.pacienteId && c.escopo.includes("ver_plano"))) return true;
  }
  // Enfermagem: somente atendimentos em que tem vínculo assistencial.
  if (profissionalApto(ator, p.instituicaoId, "enfermagem") && p.equipe.includes(ator.userId)) return true;
  // Revisor clínico: atendimentos da própria instituição.
  if (profissionalApto(ator, p.instituicaoId, "revisor")) return true;
  // Admin e auditor não têm acesso clínico por padrão.
  return false;
}

export function podeCriarOuEditarRascunho(ator: Ator, p: Omit<FatosPlano, "status" | "autorId">): boolean {
  return profissionalApto(ator, p.instituicaoId, "enfermagem", "revisor") && (
    temPapel(ator, p.instituicaoId, "revisor") || p.equipe.includes(ator.userId)
  );
}

export function podeEditarPlano(ator: Ator, p: FatosPlano): boolean {
  return p.status === "rascunho" && podeCriarOuEditarRascunho(ator, p);
}

export function podeEnviarParaRevisao(ator: Ator, p: FatosPlano): boolean {
  return p.status === "rascunho" && podeCriarOuEditarRascunho(ator, p);
}

/** Separação de funções: quem escreveu a versão não a aprova. */
export function podeAprovarEPublicar(ator: Ator, p: FatosPlano): boolean {
  return p.status === "em_revisao" && profissionalApto(ator, p.instituicaoId, "revisor") && p.autorId !== ator.userId;
}

export function podeDevolverParaRascunho(ator: Ator, p: FatosPlano): boolean {
  return p.status === "em_revisao" && profissionalApto(ator, p.instituicaoId, "revisor");
}

export function podeConvidarPaciente(ator: Ator, p: Pick<FatosPlano, "instituicaoId" | "equipe">): boolean {
  return profissionalApto(ator, p.instituicaoId, "enfermagem", "revisor") && (
    temPapel(ator, p.instituicaoId, "revisor") || p.equipe.includes(ator.userId)
  );
}

export function podeRegistrarDose(ator: Ator, pacienteId: string): boolean {
  if (ator.pacientesProprios.includes(pacienteId)) return true;
  return ator.cuidadorDe.some((c) => c.pacienteId === pacienteId && c.escopo.includes("registrar_dose"));
}

/** Só o próprio paciente concede ou revoga acesso de cuidadores. */
export function podeGerenciarCuidadores(ator: Ator, pacienteId: string): boolean {
  return ator.pacientesProprios.includes(pacienteId);
}

export function podeConsultarAuditoria(ator: Ator, instituicaoId: string): boolean {
  return profissionalApto(ator, instituicaoId, "auditor", "admin");
}

export class AcessoNegado extends Error {
  constructor(public readonly acao: string) {
    super("Acesso negado.");
  }
}

