import { and, asc, eq, inArray } from "drizzle-orm";
import { auditar } from "../auditoria";
import { podeVerPlano, type Ator } from "../authz/politicas";
import { db } from "../db/cliente";
import { plano, user } from "../db/schema";
import { conteudoPlanoSchema, type ConteudoPlano, type MedicamentoPlano } from "./conteudo";

export type Mudanca = {
  secao: "Remédios" | "Cuidados" | "Quando procurar ajuda" | "Retorno" | "Contato";
  tipo: "incluido" | "removido" | "alterado";
  titulo: string;
  antes?: string;
  depois?: string;
};

const horarios = (m: MedicamentoPlano) =>
  m.seNecessario ? `se necessário (${m.seNecessario.quando}; mín. ${m.seNecessario.intervaloMinimoHoras} h; máx. ${m.seNecessario.maximoPorDia}/dia)` : m.horarios.join(", ");
const duracao = (m: MedicamentoPlano) => (m.duracaoDias === null ? "uso contínuo" : `${m.duracaoDias} dias`);

const CAMPOS_MED: [string, (m: MedicamentoPlano) => string][] = [
  ["Dose", (m) => m.dose],
  ["Como usar", (m) => m.via],
  ["Horários", horarios],
  ["Duração", duracao],
  ["Observação", (m) => m.observacao ?? "—"],
  ["Para que serve", (m) => m.finalidade],
];

const ROTULO_NIVEL = { urgencia: "Urgência", contato: "Contato com a unidade", previsto: "Cuidado previsto" } as const;

/** Compara duas versões publicadas. Função pura, testável. */
export function compararConteudos(antes: ConteudoPlano, depois: ConteudoPlano): Mudanca[] {
  const mudancas: Mudanca[] = [];

  const medAntes = new Map(antes.medicamentos.map((m) => [m.id, m]));
  const medDepois = new Map(depois.medicamentos.map((m) => [m.id, m]));
  for (const [id, m] of medDepois) {
    const a = medAntes.get(id);
    if (!a) {
      mudancas.push({ secao: "Remédios", tipo: "incluido", titulo: m.nome, depois: `${m.dose} · ${horarios(m)} · ${duracao(m)}` });
      continue;
    }
    if (a.nome !== m.nome) mudancas.push({ secao: "Remédios", tipo: "alterado", titulo: "Nome do medicamento", antes: a.nome, depois: m.nome });
    for (const [rotulo, f] of CAMPOS_MED) {
      if (f(a) !== f(m)) mudancas.push({ secao: "Remédios", tipo: "alterado", titulo: `${m.nome}: ${rotulo}`, antes: f(a), depois: f(m) });
    }
  }
  for (const [id, m] of medAntes) {
    if (!medDepois.has(id)) mudancas.push({ secao: "Remédios", tipo: "removido", titulo: m.nome, antes: `${m.dose} · ${horarios(m)}` });
  }

  const cuidAntes = new Map(antes.cuidados.map((c) => [c.titulo, c.texto]));
  const cuidDepois = new Map(depois.cuidados.map((c) => [c.titulo, c.texto]));
  for (const [t, texto] of cuidDepois) {
    if (!cuidAntes.has(t)) mudancas.push({ secao: "Cuidados", tipo: "incluido", titulo: t, depois: texto });
    else if (cuidAntes.get(t) !== texto) mudancas.push({ secao: "Cuidados", tipo: "alterado", titulo: t, antes: cuidAntes.get(t), depois: texto });
  }
  for (const [t, texto] of cuidAntes) if (!cuidDepois.has(t)) mudancas.push({ secao: "Cuidados", tipo: "removido", titulo: t, antes: texto });

  const chave = (s: { nivel: string; texto: string }) => `${s.nivel}|${s.texto}`;
  const sinAntes = new Set(antes.sinais.map(chave));
  const sinDepois = new Set(depois.sinais.map(chave));
  for (const s of depois.sinais) if (!sinAntes.has(chave(s))) mudancas.push({ secao: "Quando procurar ajuda", tipo: "incluido", titulo: ROTULO_NIVEL[s.nivel], depois: s.texto });
  for (const s of antes.sinais) if (!sinDepois.has(chave(s))) mudancas.push({ secao: "Quando procurar ajuda", tipo: "removido", titulo: ROTULO_NIVEL[s.nivel], antes: s.texto });

  const ret = (r?: ConteudoPlano["retornos"][number]) => (r ? `${r.dataHora?.replace("T", " às ") ?? "a agendar"} · ${r.local}` : undefined);
  const n = Math.max(antes.retornos.length, depois.retornos.length);
  for (let i = 0; i < n; i++) {
    const a = ret(antes.retornos[i]);
    const d = ret(depois.retornos[i]);
    if (a !== d) mudancas.push({ secao: "Retorno", tipo: !a ? "incluido" : !d ? "removido" : "alterado", titulo: `Retorno ${i + 1}`, antes: a, depois: d });
  }

  if (antes.contato.telefone !== depois.contato.telefone || antes.contato.horarioAtendimento !== depois.contato.horarioAtendimento) {
    mudancas.push({
      secao: "Contato",
      tipo: "alterado",
      titulo: "Contato da unidade",
      antes: `${antes.contato.telefone} · ${antes.contato.horarioAtendimento}`,
      depois: `${depois.contato.telefone} · ${depois.contato.horarioAtendimento}`,
    });
  }
  return mudancas;
}

/** Histórico de versões publicadas do mesmo atendimento, com a comparação de cada uma com a anterior. */
export async function historicoDoPlano(ator: Ator, planoId: string) {
  const [atual] = await db.select().from(plano).where(eq(plano.id, planoId));
  const permitido =
    atual &&
    podeVerPlano(ator, { instituicaoId: atual.instituicaoId, pacienteId: atual.pacienteId, atendimentoId: atual.atendimentoId, status: atual.status, autorId: atual.autorId, equipe: [] }) &&
    (ator.pacientesProprios.includes(atual.pacienteId) || ator.cuidadorDe.some((c) => c.pacienteId === atual.pacienteId));
  await auditar({ atorUserId: ator.userId, instituicaoId: atual?.instituicaoId ?? null, acao: "plano.historico", recursoTipo: "plano", recursoId: planoId, resultado: permitido ? "permitido" : "negado" });
  if (!permitido) return null;

  const versoes = await db
    .select({ id: plano.id, versao: plano.versao, conteudo: plano.conteudo, publicadoEm: plano.publicadoEm, motivo: plano.motivoAlteracao, revisorId: plano.revisorId, autorId: plano.autorId })
    .from(plano)
    .where(and(eq(plano.atendimentoId, atual.atendimentoId), inArray(plano.status, ["publicado", "substituido", "encerrado"])))
    .orderBy(asc(plano.versao));
  const nomes = new Map(
    (await db.select({ id: user.id, name: user.name }).from(user).where(inArray(user.id, versoes.flatMap((v) => [v.autorId, v.revisorId ?? v.autorId])))).map((u) => [u.id, u.name]),
  );
  return versoes.map((v, i) => ({
    versao: v.versao,
    publicadoEm: v.publicadoEm,
    motivo: v.motivo,
    autor: nomes.get(v.autorId) ?? "—",
    revisor: v.revisorId ? (nomes.get(v.revisorId) ?? "—") : null,
    atual: v.id === planoId,
    mudancas: i === 0 ? null : compararConteudos(conteudoPlanoSchema.parse(versoes[i - 1].conteudo), conteudoPlanoSchema.parse(v.conteudo)),
  }));
}

import { createHash } from "node:crypto";
import { desc, eq } from "drizzle-orm";
import { z } from "zod";
import { auditar } from "../auditoria";
import { AcessoNegado, podeVerPlano, type Ator } from "../authz/politicas";
import { db } from "../db/cliente";
import { confirmacaoEntendimento, plano, user, type RespostaEntendimento } from "../db/schema";
import { conteudoPlanoSchema, type ConteudoPlano } from "./conteudo";
import { abrirPendencia } from "./pendencias";

// Confirmação de entendimento (inspirada no "teach-back" do AHRQ RED, ver
// docs/pesquisa.md). As perguntas são geradas DE FORMA DETERMINÍSTICA a partir
// do próprio plano aprovado — sem IA e sem conteúdo clínico novo. A correção
// acontece sempre no servidor. Acertar não certifica compreensão: erros e
// "não sei" viram pendência para a equipe reforçar a orientação.

export type Opcao = { id: string; texto: string };
export type Pergunta = { id: string; enunciado: string; opcoes: Opcao[]; secao: "remedios" | "ajuda"; correta: string };

const NAO_SEI: Opcao = { id: "nao-sei", texto: "Não sei / prefiro perguntar à equipe" };

const id = (...partes: string[]) => createHash("sha256").update(partes.join("|")).digest("hex").slice(0, 12);

/** Embaralha de forma estável (mesma ordem a cada carregamento). */
function embaralhar<T extends { id: string }>(itens: T[], semente: string): T[] {
  return [...itens].sort((a, b) => id(semente, a.id).localeCompare(id(semente, b.id)));
}

function deslocar(hhmm: string, horas: number) {
  const [h, m] = hhmm.split(":").map(Number);
  return `${String((h + horas + 24) % 24).padStart(2, "0")}:${String(m).padStart(2, "0")}`;
}

const listaHoras = (hs: string[]) => hs.map((h) => h.replace(":00", "h").replace(":", "h")).join(", ");

export function gerarPerguntas(conteudo: ConteudoPlano): Pergunta[] {
  const perguntas: Pergunta[] = [];

  for (const m of conteudo.medicamentos.filter((x) => x.horarios.length > 0).slice(0, 2)) {
    const certa = listaHoras(m.horarios);
    const candidatas = [listaHoras(m.horarios.map((h) => deslocar(h, 2))), listaHoras([m.horarios[0]]), listaHoras([...m.horarios, deslocar(m.horarios.at(-1)!, 4)])];
    const distratoras = [...new Set(candidatas)].filter((t) => t !== certa).slice(0, 2);
    const pid = id("horario", m.id);
    const opcoes = embaralhar([{ id: id(pid, certa), texto: certa }, ...distratoras.map((t) => ({ id: id(pid, t), texto: t }))], pid);
    perguntas.push({ id: pid, enunciado: `Em quais horários você deve usar ${m.nome}?`, opcoes: [...opcoes, NAO_SEI], secao: "remedios", correta: id(pid, certa) });
  }

  const sn = conteudo.medicamentos.find((x) => x.seNecessario);
  if (sn?.seNecessario) {
    const pid = id("se-necessario", sn.id);
    const certa = { id: id(pid, "sn"), texto: `Somente se necessário: ${sn.seNecessario.quando}` };
    const errada = { id: id(pid, "fixo"), texto: "Todos os dias, em horário fixo, mesmo sem precisar" };
    perguntas.push({ id: pid, enunciado: `Quando usar ${sn.nome}?`, opcoes: [...embaralhar([certa, errada], pid), NAO_SEI], secao: "remedios", correta: certa.id });
  }

  const grupos = [
    { nivel: "urgencia", texto: "Procurar atendimento de urgência, conforme a orientação recebida" },
    { nivel: "contato", texto: "Entrar em contato com a unidade" },
    { nivel: "previsto", texto: "Seguir os cuidados previstos no plano" },
  ] as const;
  for (const nivel of ["urgencia", "contato"] as const) {
    const sinal = conteudo.sinais.find((s) => s.nivel === nivel);
    if (!sinal) continue;
    const pid = id("sinal", nivel, sinal.texto);
    const opcoes = grupos.map((g) => ({ id: id(pid, g.nivel), texto: g.texto }));
    perguntas.push({
      id: pid,
      enunciado: `Se acontecer: “${sinal.texto}”. O que o seu plano orienta?`,
      opcoes: [...embaralhar(opcoes, pid), NAO_SEI],
      secao: "ajuda",
      correta: id(pid, nivel),
    });
  }
  return perguntas;
}

/** Perguntas sem a resposta certa, para enviar ao navegador. */
export function perguntasPublicas(conteudo: ConteudoPlano) {
  return gerarPerguntas(conteudo).map((p) => ({ id: p.id, enunciado: p.enunciado, opcoes: p.opcoes, secao: p.secao }));
}

async function planoVisivel(ator: Ator, planoId: string) {
  const [p] = await db.select().from(plano).where(eq(plano.id, planoId));
  const permitido =
    p &&
    p.status === "publicado" &&
    podeVerPlano(ator, { instituicaoId: p.instituicaoId, pacienteId: p.pacienteId, atendimentoId: p.atendimentoId, status: p.status, autorId: p.autorId, equipe: [] }) &&
    (ator.pacientesProprios.includes(p.pacienteId) || ator.cuidadorDe.some((c) => c.pacienteId === p.pacienteId));
  return permitido ? p : null;
}

export async function lerQuestionario(ator: Ator, planoId: string) {
  const p = await planoVisivel(ator, planoId);
  if (!p) return null;
  const conteudo = conteudoPlanoSchema.parse(p.conteudo);
  return { versao: p.versao, perguntas: perguntasPublicas(conteudo) };
}

const respostasSchema = z.record(z.string().regex(/^[0-9a-f]{12}$/), z.string().regex(/^([0-9a-f]{12}|nao-sei)$/));

export async function responderQuestionario(ator: Ator, planoId: string, entrada: unknown) {
  const p = await planoVisivel(ator, planoId);
  if (!p) {
    await auditar({ atorUserId: ator.userId, acao: "entendimento.responder", recursoTipo: "plano", recursoId: planoId, resultado: "negado" });
    throw new AcessoNegado("entendimento.responder");
  }
  const respostas = respostasSchema.parse(entrada);
  const perguntas = gerarPerguntas(conteudoPlanoSchema.parse(p.conteudo));
  const avaliadas: RespostaEntendimento[] = perguntas.map((q) => ({
    perguntaId: q.id,
    escolha: respostas[q.id] ?? "nao-sei",
    correta: respostas[q.id] === q.correta,
  }));
  const acertos = avaliadas.filter((r) => r.correta).length;

  await db.insert(confirmacaoEntendimento).values({ planoId: p.id, pacienteId: p.pacienteId, respondidoPor: ator.userId, respostas: avaliadas, acertos, total: perguntas.length });

  const reforcar = perguntas.filter((q) => !avaliadas.find((a) => a.perguntaId === q.id)?.correta);
  if (reforcar.length) {
    await abrirPendencia({
      instituicaoId: p.instituicaoId,
      pacienteId: p.pacienteId,
      planoId: p.id,
      tipo: "entendimento",
      descricao: `Reforçar ${reforcar.length} de ${perguntas.length} pontos: ${reforcar.map((q) => q.enunciado).join(" | ")}`,
      chave: `entendimento:${p.id}:${ator.userId}`,
      criadoPor: ator.userId,
    });
  }
  await auditar({ atorUserId: ator.userId, instituicaoId: p.instituicaoId, acao: "entendimento.responder", recursoTipo: "plano", recursoId: p.id, resultado: "permitido", detalhes: { acertos, total: perguntas.length } });

  return {
    acertos,
    total: perguntas.length,
    resultado: perguntas.map((q) => ({
      id: q.id,
      enunciado: q.enunciado,
      secao: q.secao,
      correta: avaliadas.find((a) => a.perguntaId === q.id)!.correta,
      respostaCerta: q.opcoes.find((o) => o.id === q.correta)!.texto,
    })),
  };
}

/** Para a equipe: histórico de confirmações do plano (já autorizado pela página). */
export async function confirmacoesDoPlano(planoId: string) {
  return db
    .select({ acertos: confirmacaoEntendimento.acertos, total: confirmacaoEntendimento.total, criadoEm: confirmacaoEntendimento.criadoEm, por: user.name })
    .from(confirmacaoEntendimento)
    .innerJoin(user, eq(user.id, confirmacaoEntendimento.respondidoPor))
    .where(eq(confirmacaoEntendimento.planoId, planoId))
    .orderBy(desc(confirmacaoEntendimento.criadoEm));
}

import { and, desc, eq, inArray } from "drizzle-orm";
import { auditar } from "../auditoria";
import { AcessoNegado, podeConsultarAuditoria, temPapel, type Ator } from "../authz/politicas";
import { db } from "../db/cliente";
import { auditoria, instituicao, session, user, vinculo } from "../db/schema";

// Administração institucional: gerencia vínculos, sem acesso clínico.

function instituicoesAdmin(ator: Ator) {
  return ator.mfaAtivo ? ator.vinculos.filter((v) => v.papel === "admin").map((v) => v.instituicaoId) : [];
}

export async function listarEquipe(ator: Ator) {
  const ids = instituicoesAdmin(ator);
  if (!ids.length) return [];
  return db
    .select({
      vinculoId: vinculo.id,
      instituicao: instituicao.nome,
      nome: user.name,
      email: user.email,
      papel: vinculo.papel,
      ativo: vinculo.ativo,
      desativadoEm: vinculo.desativadoEm,
      mfa: user.twoFactorEnabled,
      userId: user.id,
    })
    .from(vinculo)
    .innerJoin(user, eq(user.id, vinculo.userId))
    .innerJoin(instituicao, eq(instituicao.id, vinculo.instituicaoId))
    .where(inArray(vinculo.instituicaoId, ids))
    .orderBy(user.name);
}

/**
 * Desligamento/retirada de papel: desativa o vínculo e encerra TODAS as
 * sessões da pessoa (efeito imediato, inclusive em outros aparelhos).
 */
export async function alterarVinculo(ator: Ator, vinculoId: string, ativo: boolean) {
  const [v] = await db.select().from(vinculo).where(eq(vinculo.id, vinculoId));
  if (!v || !ator.mfaAtivo || !temPapel(ator, v.instituicaoId, "admin") || v.userId === ator.userId) {
    await auditar({ atorUserId: ator.userId, acao: "vinculo.alterar", recursoTipo: "vinculo", recursoId: vinculoId, resultado: "negado" });
    throw new AcessoNegado("vinculo.alterar");
  }
  await db.transaction(async (tx) => {
    await tx.update(vinculo).set({ ativo, desativadoEm: ativo ? null : new Date() }).where(eq(vinculo.id, vinculoId));
    if (!ativo) await tx.delete(session).where(eq(session.userId, v.userId));
    await auditar({ atorUserId: ator.userId, instituicaoId: v.instituicaoId, acao: ativo ? "vinculo.reativar" : "vinculo.desativar", recursoTipo: "vinculo", recursoId: vinculoId, resultado: "permitido" }, tx);
  });
}

/** Trilha de auditoria com exposição mínima: sem conteúdo clínico, sem nome de paciente. */
export async function consultarAuditoria(ator: Ator, filtro: { somenteNegados?: boolean } = {}) {
  const ids = [...new Set(ator.vinculos.map((v) => v.instituicaoId))].filter((i) => podeConsultarAuditoria(ator, i));
  if (!ids.length) throw new AcessoNegado("auditoria.consultar");
  await auditar({ atorUserId: ator.userId, instituicaoId: ids[0], acao: "auditoria.consultar", resultado: "permitido" });
  return db
    .select({
      id: auditoria.id,
      ocorridoEm: auditoria.ocorridoEm,
      acao: auditoria.acao,
      recursoTipo: auditoria.recursoTipo,
      recursoId: auditoria.recursoId,
      resultado: auditoria.resultado,
      ator: user.name,
    })
    .from(auditoria)
    .leftJoin(user, eq(user.id, auditoria.atorUserId))
    .where(and(inArray(auditoria.instituicaoId, ids), filtro.somenteNegados ? eq(auditoria.resultado, "negado") : undefined))
    .orderBy(desc(auditoria.ocorridoEm))
    .limit(200);
}

import { and, eq, gt, inArray, isNull, lte, ne, or, sql } from "drizzle-orm";
import { auditar } from "../auditoria";
import { db, type Tx } from "../db/cliente";
import { autorizacaoCuidador, lembrete, paciente, plano, preferenciaLembrete, user } from "../db/schema";
import { enviarMensagem } from "../mensagens";
import { conteudoPlanoSchema } from "./conteudo";

// Lembretes agendados no servidor (seção 16 do documento de requisitos):
// fuso do plano, cancelamento por nova versão, idempotência (índice único),
// tentativas limitadas e mensagem discreta. "Enviado" ≠ visto ou seguido.

export const DIAS_A_FRENTE = 7;
export const MAX_TENTATIVAS = 3;
/** Lembrete atrasado mais que isso não é enviado (evita aviso fora de hora). */
export const ATRASO_MAXIMO_MIN = 60;

/** Converte data e hora locais de um fuso em instante UTC. */
export function instanteNoFuso(data: string, hhmm: string, fuso: string): Date {
  const [y, mo, d] = data.split("-").map(Number);
  const [h, mi] = hhmm.split(":").map(Number);
  const palpite = Date.UTC(y, mo - 1, d, h, mi);
  const deslocamento = (instante: number) => {
    const p = Object.fromEntries(
      new Intl.DateTimeFormat("en-US", { timeZone: fuso, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit" })
        .formatToParts(new Date(instante))
        .map((x) => [x.type, x.value]),
    );
    return Date.UTC(+p.year, +p.month - 1, +p.day, +p.hour, +p.minute) - instante;
  };
  const primeiro = palpite - deslocamento(palpite);
  return new Date(palpite - deslocamento(primeiro));
}

function dataNoFuso(instante: Date, fuso: string) {
  return new Intl.DateTimeFormat("en-CA", { timeZone: fuso }).format(instante);
}

function somarDias(data: string, n: number) {
  const d = new Date(`${data}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
}

/** Quem recebe lembretes deste paciente: o próprio e cuidadores ativos, se escolheram receber. */
async function destinatarios(pacienteId: string, tx: Tx | typeof db = db): Promise<string[]> {
  const agora = new Date();
  const [pac] = await tx.select({ userId: paciente.userId }).from(paciente).where(eq(paciente.id, pacienteId));
  const cuidadores = await tx
    .select({ userId: autorizacaoCuidador.cuidadorUserId })
    .from(autorizacaoCuidador)
    .where(
      and(
        eq(autorizacaoCuidador.pacienteId, pacienteId),
        isNull(autorizacaoCuidador.revogadoEm),
        or(isNull(autorizacaoCuidador.expiraEm), gt(autorizacaoCuidador.expiraEm, agora)),
      ),
    );
  const candidatos = [pac?.userId, ...cuidadores.map((c) => c.userId)].filter((x): x is string => Boolean(x));
  if (!candidatos.length) return [];
  const ativos = await tx
    .select({ userId: preferenciaLembrete.userId })
    .from(preferenciaLembrete)
    .where(and(inArray(preferenciaLembrete.userId, candidatos), eq(preferenciaLembrete.ativo, true)));
  return ativos.map((a) => a.userId);
}

/** Cria (idempotente) os lembretes dos próximos dias para um plano publicado. */
export async function agendarLembretesDoPlano(planoId: string, agora = new Date(), tx: Tx | typeof db = db) {
  const [p] = await tx.select().from(plano).where(eq(plano.id, planoId));
  if (!p || p.status !== "publicado") return 0;
  const conteudo = conteudoPlanoSchema.parse(p.conteudo);
  const usuarios = await destinatarios(p.pacienteId, tx);
  if (!usuarios.length) return 0;

  const hoje = dataNoFuso(agora, conteudo.fusoHorario);
  const linhas: (typeof lembrete.$inferInsert)[] = [];
  for (let i = 0; i < DIAS_A_FRENTE; i++) {
    const data = somarDias(hoje, i);
    const indice = (Date.parse(`${data}T00:00:00Z`) - Date.parse(`${conteudo.inicio}T00:00:00Z`)) / 86_400_000;
    if (indice < 0) continue;
    for (const m of conteudo.medicamentos) {
      if (!m.horarios.length || (m.duracaoDias !== null && indice >= m.duracaoDias)) continue;
      for (const h of m.horarios) {
        const instante = instanteNoFuso(data, h, conteudo.fusoHorario);
        if (instante <= agora) continue;
        for (const userId of usuarios) linhas.push({ planoId: p.id, userId, itemId: m.id, agendadoPara: instante });
      }
    }
  }
  if (!linhas.length) return 0;
  const criadas = await tx.insert(lembrete).values(linhas).onConflictDoNothing().returning({ id: lembrete.id });
  return criadas.length;
}

/** Nova versão publicada: cancela os lembretes pendentes das versões anteriores do mesmo atendimento. */
export async function cancelarLembretesDeOutrasVersoes(atendimentoId: string, planoVigenteId: string, tx: Tx | typeof db = db) {
  const r = await tx
    .update(lembrete)
    .set({ status: "cancelado", ultimoErro: "substituido_por_nova_versao" })
    .where(
      and(
        eq(lembrete.status, "agendado"),
        ne(lembrete.planoId, planoVigenteId),
        inArray(lembrete.planoId, tx.select({ id: plano.id }).from(plano).where(eq(plano.atendimentoId, atendimentoId))),
      ),
    )
    .returning({ id: lembrete.id });
  return r.length;
}

/** Liga ou desliga os lembretes do próprio usuário. */
export async function definirPreferenciaLembrete(userId: string, ativo: boolean) {
  await db
    .insert(preferenciaLembrete)
    .values({ userId, ativo })
    .onConflictDoUpdate({ target: preferenciaLembrete.userId, set: { ativo, atualizadoEm: new Date() } });
  if (!ativo) {
    await db.update(lembrete).set({ status: "cancelado", ultimoErro: "desativado_pelo_usuario" }).where(and(eq(lembrete.userId, userId), eq(lembrete.status, "agendado")));
  }
  await auditar({ atorUserId: userId, acao: "lembrete.preferencia", resultado: "permitido", detalhes: { ativo } });
}

export async function preferenciaDe(userId: string) {
  const [p] = await db.select({ ativo: preferenciaLembrete.ativo }).from(preferenciaLembrete).where(eq(preferenciaLembrete.userId, userId));
  return p?.ativo ?? false;
}

/** Mensagem discreta: sem nome de medicamento, diagnóstico ou procedimento. */
export const TEXTO_LEMBRETE = "Lembrete do Alta Clara: há um horário planejado agora. Abra o aplicativo para ver o que fazer.";

/**
 * Processa os lembretes vencidos. Seguro para mais de um processador ao mesmo
 * tempo (FOR UPDATE SKIP LOCKED). Revalida tudo antes de enviar.
 */
export async function processarLembretes(agora = new Date(), enviar = enviarMensagem) {
  const resumo = { enviados: 0, cancelados: 0, falhas: 0 };
  const lote = await db.transaction(async (tx) => {
    const devidos = await tx
      .select({ id: lembrete.id, planoId: lembrete.planoId, userId: lembrete.userId, agendadoPara: lembrete.agendadoPara, tentativas: lembrete.tentativas })
      .from(lembrete)
      .where(and(eq(lembrete.status, "agendado"), lte(lembrete.agendadoPara, agora)))
      .limit(50)
      .for("update", { skipLocked: true });
    const resultado: { id: string; email: string | null; motivo: string | null; tentativas: number }[] = [];
    for (const l of devidos) {
      const [p] = await tx.select({ status: plano.status, pacienteId: plano.pacienteId }).from(plano).where(eq(plano.id, l.planoId));
      let motivo: string | null = null;
      if (!p || p.status !== "publicado") motivo = "plano_nao_vigente";
      else if (agora.getTime() - l.agendadoPara.getTime() > ATRASO_MAXIMO_MIN * 60_000) motivo = "atrasado";
      else if (!(await destinatarios(p.pacienteId, tx)).includes(l.userId)) motivo = "sem_autorizacao_ou_desativado";
      const [u] = await tx.select({ email: user.email }).from(user).where(eq(user.id, l.userId));
      resultado.push({ id: l.id, email: u?.email ?? null, motivo, tentativas: l.tentativas });
      // Marca a tentativa antes de enviar: se o processo cair, não repete além do limite.
      await tx.update(lembrete).set({ tentativas: sql`${lembrete.tentativas} + 1` }).where(eq(lembrete.id, l.id));
    }
    return resultado;
  });

  for (const l of lote) {
    if (l.motivo || !l.email) {
      await db.update(lembrete).set({ status: "cancelado", ultimoErro: l.motivo ?? "sem_email" }).where(eq(lembrete.id, l.id));
      resumo.cancelados++;
      continue;
    }
    try {
      await enviar({ para: l.email, assunto: "Lembrete do Alta Clara", corpo: TEXTO_LEMBRETE });
      await db.update(lembrete).set({ status: "enviado", enviadoEm: new Date() }).where(eq(lembrete.id, l.id));
      resumo.enviados++;
    } catch (e) {
      const esgotou = l.tentativas + 1 >= MAX_TENTATIVAS;
      await db
        .update(lembrete)
        .set({ status: esgotou ? "falhou" : "agendado", ultimoErro: e instanceof Error ? e.name : "erro" })
        .where(eq(lembrete.id, l.id));
      resumo.falhas++;
    }
  }
  return resumo;
}

/** Mantém a janela de 7 dias para todos os planos publicados (rodado pelo processador). */
export async function renovarAgendas(agora = new Date()) {
  const publicados = await db.select({ id: plano.id }).from(plano).where(eq(plano.status, "publicado"));
  let criados = 0;
  for (const p of publicados) criados += await agendarLembretesDoPlano(p.id, agora);
  return criados;
}

import { and, eq, inArray, isNull, sql } from "drizzle-orm";
import { auditar } from "../auditoria";
import { AcessoNegado, podeRegistrarDose, podeVerPlano, type Ator } from "../authz/politicas";
import { db } from "../db/cliente";
import { atendimento, instituicao, paciente, pendencia as pendenciaTabela, plano, registroDose, user } from "../db/schema";
import { conteudoPlanoSchema } from "./conteudo";
import { abrirPendencia } from "./pendencias";

/** Pacientes que o ator pode acompanhar (os próprios e os autorizados). */
function pacientesVisiveis(ator: Ator): string[] {
  return [
    ...ator.pacientesProprios,
    ...ator.cuidadorDe.filter((c) => c.escopo.includes("ver_plano")).map((c) => c.pacienteId),
  ];
}

/** Planos publicados vigentes que o paciente/cuidador pode ver. */
export async function listarPlanosVigentes(ator: Ator) {
  const ids = pacientesVisiveis(ator);
  if (!ids.length) return [];
  return db
    .select({
      planoId: plano.id,
      versao: plano.versao,
      publicadoEm: plano.publicadoEm,
      pacienteId: paciente.id,
      pacienteNome: paciente.nome,
      procedimento: atendimento.procedimento,
      instituicao: instituicao.nome,
      proprio: sql<boolean>`${paciente.userId} = ${ator.userId}`,
    })
    .from(plano)
    .innerJoin(paciente, eq(paciente.id, plano.pacienteId))
    .innerJoin(atendimento, eq(atendimento.id, plano.atendimentoId))
    .innerJoin(instituicao, eq(instituicao.id, plano.instituicaoId))
    .where(and(inArray(plano.pacienteId, ids), eq(plano.status, "publicado")));
}

/** Plano completo para a tela do paciente, com autorização por objeto. */
export async function lerPlanoDoPaciente(ator: Ator, planoId: string) {
  const [linha] = await db
    .select({
      plano,
      procedimento: atendimento.procedimento,
      instituicao: instituicao.nome,
      autorNome: sql<string>`(select name from ${user} where id = ${plano.autorId})`,
      revisorNome: sql<string | null>`(select name from ${user} where id = ${plano.revisorId})`,
    })
    .from(plano)
    .innerJoin(atendimento, eq(atendimento.id, plano.atendimentoId))
    .innerJoin(instituicao, eq(instituicao.id, plano.instituicaoId))
    .where(eq(plano.id, planoId));

  const permitido =
    linha &&
    podeVerPlano(ator, {
      instituicaoId: linha.plano.instituicaoId,
      pacienteId: linha.plano.pacienteId,
      atendimentoId: linha.plano.atendimentoId,
      status: linha.plano.status,
      autorId: linha.plano.autorId,
      equipe: [],
    }) &&
    pacientesVisiveis(ator).includes(linha.plano.pacienteId);

  await auditar({
    atorUserId: ator.userId,
    instituicaoId: linha?.plano.instituicaoId ?? null,
    acao: "plano.ler_paciente",
    recursoTipo: "plano",
    recursoId: planoId,
    resultado: permitido ? "permitido" : "negado",
  });
  if (!permitido) return null;

  const registros = await db
    .select({
      itemId: registroDose.itemId,
      data: registroDose.data,
      horario: registroDose.horario,
      situacao: registroDose.situacao,
      por: user.name,
      proprio: sql<boolean>`${registroDose.registradoPor} = ${ator.userId}`,
    })
    .from(registroDose)
    .innerJoin(user, eq(user.id, registroDose.registradoPor))
    .where(eq(registroDose.planoId, planoId));

  return {
    id: linha.plano.id,
    versao: linha.plano.versao,
    status: linha.plano.status,
    publicadoEm: linha.plano.publicadoEm,
    conteudo: conteudoPlanoSchema.parse(linha.plano.conteudo),
    procedimento: linha.procedimento,
    instituicao: linha.instituicao,
    autorNome: linha.autorNome,
    revisorNome: linha.revisorNome,
    podeRegistrar: linha.plano.status === "publicado" && podeRegistrarDose(ator, linha.plano.pacienteId),
    registros,
  };
}

export type Situacao = "relatou_tomada" | "nao_tomou" | "duvida";

/**
 * Registro relatado (não comprova ingestão). Idempotente: a mesma dose
 * marcada duas vezes, ou por dois cuidadores ao mesmo tempo, gera um registro.
 */
export async function registrarDose(
  ator: Ator,
  entrada: { planoId: string; itemId: string; data: string; horario: string; situacao: Situacao | null },
) {
  const [p] = await db.select().from(plano).where(eq(plano.id, entrada.planoId));
  if (!p || p.status !== "publicado" || !podeRegistrarDose(ator, p.pacienteId)) {
    await auditar({ atorUserId: ator.userId, acao: "dose.registrar", recursoTipo: "plano", recursoId: entrada.planoId, resultado: "negado" });
    throw new AcessoNegado("dose.registrar");
  }

  // A dose precisa existir na prescrição revisada desta versão.
  const conteudo = conteudoPlanoSchema.parse(p.conteudo);
  const item = conteudo.medicamentos.find((m) => m.id === entrada.itemId);
  if (!item || !item.horarios.includes(entrada.horario) || !/^\d{4}-\d{2}-\d{2}$/.test(entrada.data)) {
    throw new AcessoNegado("dose.registrar");
  }
  const dia = (Date.parse(`${entrada.data}T00:00:00Z`) - Date.parse(`${conteudo.inicio}T00:00:00Z`)) / 86_400_000;
  if (dia < 0 || (item.duracaoDias !== null && dia >= item.duracaoDias)) throw new AcessoNegado("dose.registrar");

  if (entrada.situacao === null) {
    await db
      .delete(registroDose)
      .where(
        and(
          eq(registroDose.planoId, p.id),
          eq(registroDose.itemId, item.id),
          eq(registroDose.data, entrada.data),
          eq(registroDose.horario, entrada.horario),
        ),
      );
  } else {
    await db
      .insert(registroDose)
      .values({
        planoId: p.id,
        pacienteId: p.pacienteId,
        itemId: item.id,
        data: entrada.data,
        horario: entrada.horario,
        situacao: entrada.situacao,
        registradoPor: ator.userId,
      })
      .onConflictDoUpdate({
        target: [registroDose.planoId, registroDose.itemId, registroDose.data, registroDose.horario],
        set: { situacao: entrada.situacao, registradoPor: ator.userId, registradoEm: new Date() },
      });
  }
  if (entrada.situacao === "duvida") {
    await abrirPendencia({
      instituicaoId: p.instituicaoId,
      pacienteId: p.pacienteId,
      planoId: p.id,
      tipo: "duvida_dose",
      descricao: `Dúvida registrada sobre ${item.nome} (${entrada.data} às ${entrada.horario}).`,
      chave: `duvida:${p.id}:${item.id}:${entrada.data}:${entrada.horario}`,
      criadoPor: ator.userId,
    });
  }
  await auditar({
    atorUserId: ator.userId,
    instituicaoId: p.instituicaoId,
    acao: "dose.registrar",
    recursoTipo: "plano",
    recursoId: p.id,
    resultado: "permitido",
    detalhes: { situacao: entrada.situacao },
  });
}

const LIMITE_SOLICITACOES_ABERTAS = 5;

/** Pedido de ajuda do paciente/cuidador: vira pendência para a equipe. Não é canal de urgência. */
export async function solicitarAjuda(ator: Ator, entrada: { planoId: string; tipo: "dificuldade_medicamento" | "duvida_geral"; texto: string }) {
  const [p] = await db.select().from(plano).where(eq(plano.id, entrada.planoId));
  const pode = p && p.status === "publicado" && (ator.pacientesProprios.includes(p.pacienteId) || ator.cuidadorDe.some((c) => c.pacienteId === p.pacienteId && c.escopo.includes("ver_plano")));
  if (!pode) {
    await auditar({ atorUserId: ator.userId, acao: "pendencia.solicitar", recursoTipo: "plano", recursoId: entrada.planoId, resultado: "negado" });
    throw new AcessoNegado("pendencia.solicitar");
  }
  const texto = entrada.texto.trim().slice(0, 300);
  if (texto.length < 3) throw new AcessoNegado("pendencia.solicitar");
  const [{ n }] = await db
    .select({ n: sql<number>`count(*)::int` })
    .from(pendenciaTabela)
    .where(and(eq(pendenciaTabela.planoId, p.id), eq(pendenciaTabela.criadoPor, ator.userId), isNull(pendenciaTabela.resolvidaEm)));
  if (n >= LIMITE_SOLICITACOES_ABERTAS) return { ok: false as const, erro: "Você já tem 5 solicitações em aberto. Aguarde o retorno da equipe ou ligue para a unidade." };
  await abrirPendencia({ instituicaoId: p.instituicaoId, pacienteId: p.pacienteId, planoId: p.id, tipo: entrada.tipo, descricao: texto, chave: null, criadoPor: ator.userId });
  await auditar({ atorUserId: ator.userId, instituicaoId: p.instituicaoId, acao: "pendencia.solicitar", recursoTipo: "plano", recursoId: p.id, resultado: "permitido", detalhes: { tipo: entrada.tipo } });
  return { ok: true as const };
}

import { and, desc, eq, inArray, isNull, sql } from "drizzle-orm";
import { auditar } from "../auditoria";
import { AcessoNegado, temPapel, type Ator } from "../authz/politicas";
import { db, type Tx } from "../db/cliente";
import { atendimento, equipeAtendimento, paciente, pendencia, plano, user } from "../db/schema";

// Pendências após a alta: tarefas operacionais para a equipe. Não
// diagnosticam, não classificam urgência e não substituem o atendimento.

export type TipoPendencia = (typeof pendencia.$inferInsert)["tipo"];

export const ROTULO_PENDENCIA: Record<TipoPendencia, string> = {
  retorno_nao_agendado: "Retorno não agendado",
  duvida_dose: "Dúvida sobre uma dose",
  entendimento: "Orientação a reforçar",
  dificuldade_medicamento: "Dificuldade para obter medicamento",
  duvida_geral: "Dúvida do paciente",
};

/** Cria se não houver outra aberta com a mesma chave (índice único parcial). */
export async function abrirPendencia(
  p: {
    instituicaoId: string;
    pacienteId: string;
    planoId: string | null;
    tipo: TipoPendencia;
    descricao: string;
    chave: string | null;
    criadoPor: string | null;
  },
  tx?: Tx,
) {
  await (tx ?? db).execute(sql`
    insert into ${pendencia} (instituicao_id, paciente_id, plano_id, tipo, descricao, chave, criado_por)
    values (${p.instituicaoId}, ${p.pacienteId}, ${p.planoId}, ${p.tipo}, ${p.descricao.slice(0, 500)}, ${p.chave}, ${p.criadoPor})
    on conflict do nothing`);
}

/** Pendências visíveis ao profissional: revisor vê a instituição; enfermagem, os pacientes da sua equipe. */
export async function listarPendencias(ator: Ator, incluirResolvidas = false) {
  if (!ator.mfaAtivo) return [];
  const instRevisor = ator.vinculos.filter((v) => v.papel === "revisor").map((v) => v.instituicaoId);
  const instEnf = ator.vinculos.filter((v) => v.papel === "enfermagem").map((v) => v.instituicaoId);
  if (!instRevisor.length && !instEnf.length) return [];

  const linhas = await db
    .select({
      id: pendencia.id,
      instituicaoId: pendencia.instituicaoId,
      tipo: pendencia.tipo,
      descricao: pendencia.descricao,
      criadoEm: pendencia.criadoEm,
      resolvidaEm: pendencia.resolvidaEm,
      resolucao: pendencia.resolucao,
      planoId: pendencia.planoId,
      atendimentoId: plano.atendimentoId,
      pacienteNome: paciente.nome,
      prontuario: paciente.prontuario,
      criadoPorNome: user.name,
      naEquipe: sql<boolean>`exists (select 1 from ${equipeAtendimento} e join ${atendimento} a on a.id = e.atendimento_id
        where a.paciente_id = ${pendencia.pacienteId} and e.user_id = ${ator.userId})`,
    })
    .from(pendencia)
    .innerJoin(paciente, eq(paciente.id, pendencia.pacienteId))
    .leftJoin(plano, eq(plano.id, pendencia.planoId))
    .leftJoin(user, eq(user.id, pendencia.criadoPor))
    .where(
      and(
        inArray(pendencia.instituicaoId, [...instRevisor, ...instEnf]),
        incluirResolvidas ? undefined : isNull(pendencia.resolvidaEm),
      ),
    )
    .orderBy(desc(pendencia.criadoEm));
  return linhas.filter((l) => instRevisor.includes(l.instituicaoId) || l.naEquipe);
}

export async function resolverPendencia(ator: Ator, id: string, resolucao: string) {
  const visiveis = await listarPendencias(ator);
  const alvo = visiveis.find((p) => p.id === id);
  if (!alvo || !temPapel(ator, alvo.instituicaoId, "enfermagem", "revisor")) {
    await auditar({ atorUserId: ator.userId, acao: "pendencia.resolver", recursoTipo: "pendencia", recursoId: id, resultado: "negado" });
    throw new AcessoNegado("pendencia.resolver");
  }
  await db
    .update(pendencia)
    .set({ resolvidaEm: new Date(), resolvidaPor: ator.userId, resolucao: resolucao.trim().slice(0, 500) })
    .where(and(eq(pendencia.id, id), isNull(pendencia.resolvidaEm)));
  await auditar({ atorUserId: ator.userId, instituicaoId: alvo.instituicaoId, acao: "pendencia.resolver", recursoTipo: "pendencia", recursoId: id, resultado: "permitido" });
}

/** Pendências abertas pelo próprio paciente/cuidador (para ele acompanhar). */
export async function pendenciasDoPlanoParaPaciente(planoId: string) {
  return db
    .select({ id: pendencia.id, tipo: pendencia.tipo, descricao: pendencia.descricao, criadoEm: pendencia.criadoEm, resolvidaEm: pendencia.resolvidaEm, resolucao: pendencia.resolucao })
    .from(pendencia)
    .where(and(eq(pendencia.planoId, planoId), inArray(pendencia.tipo, ["dificuldade_medicamento", "duvida_geral", "duvida_dose"])))
    .orderBy(desc(pendencia.criadoEm))
    .limit(20);
}

import { and, asc, desc, eq, inArray, sql } from "drizzle-orm";
import { auditar } from "../auditoria";
import {
  AcessoNegado,
  podeAprovarEPublicar,
  podeCriarOuEditarRascunho,
  podeDevolverParaRascunho,
  podeEditarPlano,
  podeEnviarParaRevisao,
  podeVerPlano,
  type Ator,
  type FatosPlano,
} from "../authz/politicas";
import { db, type Tx } from "../db/cliente";
import { atendimento, equipeAtendimento, instituicao, modeloProtocolo, paciente, plano } from "../db/schema";
import { conteudoPlanoSchema, type ConteudoPlano } from "./conteudo";
import { agendarLembretesDoPlano, cancelarLembretesDeOutrasVersoes } from "./lembretes";
