  const { id } = await props.params;
  if (!/^[0-9a-f-]{36}$/.test(id)) notFound();
  const dados = await lerPlanoParaEquipe(ator, id);
  if (!dados) notFound();

  const { plano, permissoes } = dados;
  const conteudo = conteudoPlanoSchema.parse(plano.conteudo);
  const confirmacoes = plano.status === "publicado" ? await confirmacoesDoPlano(plano.id) : [];

  return (
    <div className="space-y-6">
      <Link href={`/equipe/atendimentos/${plano.atendimentoId}`} className="font-semibold text-primary underline">
        ← Atendimento
      </Link>
      <IdentificacaoPaciente
        nome={dados.pacienteNome}
        nascimento={dados.pacienteNascimento}
        prontuario={dados.prontuario}
        instituicao={dados.instituicao}
        procedimento={dados.procedimento}
      />

      <div className="flex flex-wrap items-center gap-3">
        <h1 className="text-3xl font-extrabold">Plano — versão {plano.versao}</h1>
        <StatusPlano status={plano.status} />
      </div>
      <p className="text-muted">
        Autor: {dados.autorNome}
        {dados.revisorNome && ` · Revisor: ${dados.revisorNome}`}
        {plano.motivoAlteracao && ` · Observação: ${plano.motivoAlteracao}`}
      </p>

      {plano.status === "publicado" && (
        <section aria-labelledby="conf" className="rounded-2xl border border-line bg-surface p-5">
          <h2 id="conf" className="text-xl font-extrabold">Confirmação de entendimento</h2>
          {confirmacoes.length === 0 ? (
            <p className="mt-1 text-muted">O paciente ainda não respondeu às perguntas de confirmação.</p>
          ) : (
            <ul className="mt-2 space-y-1">
              {confirmacoes.map((c, i) => (
                <li key={i}>
                  {c.criadoEm.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" })} · {c.por}: {c.acertos} de {c.total} de acordo com o plano
                </li>
              ))}
            </ul>
          )}
          <p className="mt-2 text-sm text-muted">Resultado isolado não certifica compreensão. Pontos a reforçar aparecem em Pendências.</p>
          <p className="mt-4 border-t border-line pt-4">
            <a href={`/equipe/planos/${plano.id}/fhir`} className="font-semibold text-primary underline">
              Exportar em HL7 FHIR R4 (exemplo, sandbox)
            </a>
            <span className="block text-sm text-muted">Arquivo de exemplo com dados sintéticos. Não há conexão nem gravação em prontuário.</span>
          </p>
        </section>
      )}

      {plano.status === "rascunho" && permissoes.editar ? (
        <EditorPlano planoId={plano.id} revisaoInicial={plano.revisao} conteudoInicial={conteudo} iaDisponivel={iaDisponivel()} />
      ) : (
        <>
          {plano.status === "em_revisao" && (
            <PainelRevisao
              planoId={plano.id}
              revisao={plano.revisao}
              podePublicar={permissoes.publicar}
              podeDevolver={permissoes.devolver}
              autorEhVoce={permissoes.autorEhVoce}
            />
          )}
          <div className="overflow-hidden rounded-3xl border-2 border-line bg-bg">
            <VisaoPlano
              modo="previa"
              plano={{
                id: plano.id,
                conteudo,
                versao: plano.versao,
                publicadoEm: plano.publicadoEm?.toISOString() ?? null,
                autorNome: dados.autorNome,
                revisorNome: dados.revisorNome ?? null,
                instituicao: dados.instituicao,
                procedimento: dados.procedimento,
                registros: [],
                podeRegistrar: false,
              }}
            />
          </div>
        </>
      )}
    </div>
  );
}

"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";
import { Aviso, Botao, Campo, Cartao } from "@/components/ui";
import { devolverAcao, publicarAcao } from "../../acoes";

export function PainelRevisao({
  planoId,
  revisao,
  podePublicar,
  podeDevolver,
  autorEhVoce,
}: {
  planoId: string;
  revisao: number;
  podePublicar: boolean;
  podeDevolver: boolean;
  autorEhVoce: boolean;
}) {
  const router = useRouter();
  const [confirmacao, setConfirmacao] = useState("");
  const [conferi, setConferi] = useState(false);
  const [motivo, setMotivo] = useState("");
  const [erro, setErro] = useState<string | null>(null);
  const [ocupado, setOcupado] = useState(false);

  async function publicar(e: FormEvent) {
    e.preventDefault();
    setOcupado(true);
    setErro(null);
    const r = await publicarAcao(planoId, revisao, confirmacao);
    setOcupado(false);
    if (!r.ok) return setErro(r.erro);
    router.refresh();
  }

  async function devolver() {
    setOcupado(true);
    const r = await devolverAcao(planoId, motivo);
    setOcupado(false);
    if (!r.ok) return setErro(r.erro);
    router.refresh();
  }

  if (!podePublicar && !podeDevolver) {
    return (
      <Aviso titulo="Aguardando revisão">
        {autorEhVoce
          ? "Você preparou esta versão. Outra pessoa com perfil de revisor clínico precisa aprovar."
          : "Somente revisores clínicos da instituição podem aprovar esta versão."}
      </Aviso>
    );
  }

  return (
    <Cartao className="border-2 border-info">
      <h2 className="text-xl font-extrabold">Revisão clínica</h2>
      <p className="mt-1 text-muted">
        Confira a prévia abaixo como o paciente verá: medicamentos, doses, horários, duração e orientações de urgência.
      </p>
      {erro && (
        <div className="mt-3">
          <Aviso tom="danger">{erro}</Aviso>
        </div>
      )}
      {podePublicar && (
        <form onSubmit={publicar} className="mt-4 space-y-4">
          <label className="flex items-start gap-3">
            <input type="checkbox" checked={conferi} onChange={(e) => setConferi(e.target.checked)} className="mt-1 size-5" />
            <span>Conferi o conteúdo com a prescrição e as orientações clínicas deste paciente.</span>
          </label>
          <Campo
            id="confirmacao"
            rotulo="Digite o prontuário do paciente para confirmar"
            dica="Evita publicar no paciente errado."
            value={confirmacao}
            onChange={(e) => setConfirmacao(e.target.value)}
            autoComplete="off"
          />
          <Botao type="submit" disabled={ocupado || !conferi || !confirmacao.trim()}>
            Aprovar e publicar
          </Botao>
        </form>
      )}
      {podeDevolver && (
        <div className="mt-6 space-y-3 border-t border-line pt-4">
          <label htmlFor="motivo-devolucao" className="block font-bold">
            Devolver para ajustes
          </label>
          <textarea
            id="motivo-devolucao"
            rows={2}
            value={motivo}
            onChange={(e) => setMotivo(e.target.value)}
            className="w-full rounded-xl border-2 border-line bg-surface p-3"
            placeholder="O que precisa ser ajustado?"
          />
          <Botao variante="secundario" onClick={devolver} disabled={ocupado || motivo.trim().length < 3}>
            Devolver ao rascunho
          </Botao>
        </div>
      )}
    </Cartao>
  );
}

"use client";

import { useState } from "react";
import { sugerirSimplificacaoAcao } from "../../acoes";

type Estado =
  | { tipo: "parado" }
  | { tipo: "carregando" }
  | { tipo: "erro"; texto: string }
  | { tipo: "sugestao"; texto: string; pontos: string[] };

/** Sugestão de linguagem simples. Nada muda sem o profissional aceitar. */
export function SimplificarIA({ texto, disponivel, onAceitar }: { texto: string; disponivel: boolean; onAceitar: (novo: string) => void }) {
  const [estado, setEstado] = useState<Estado>({ tipo: "parado" });

  if (!disponivel) {
    return (
      <p className="text-sm text-muted" title="Configure ANTHROPIC_API_KEY e ALTA_IA_HABILITADA=1 para habilitar.">
        Simplificação por IA indisponível neste ambiente.
      </p>
    );
  }

  return (
    <div className="space-y-2">
      <button
        type="button"
        disabled={estado.tipo === "carregando" || texto.trim().length < 10}
        onClick={async () => {
          setEstado({ tipo: "carregando" });
          const r = await sugerirSimplificacaoAcao(texto).catch(() => ({ estado: "recusada" as const, motivo: "Falha de comunicação." }));
          if (r.estado === "ok") setEstado({ tipo: "sugestao", texto: r.sugestao.texto_simplificado, pontos: r.sugestao.pontos_de_atencao });
          else setEstado({ tipo: "erro", texto: r.estado === "indisponivel" ? "IA indisponível." : r.motivo });
        }}
        className="min-h-11 rounded-lg px-2 text-sm font-semibold text-primary underline disabled:opacity-50"
      >
        {estado.tipo === "carregando" ? "Gerando sugestão…" : "Sugerir linguagem mais simples (IA)"}
      </button>
      {estado.tipo === "erro" && <p className="text-sm font-semibold text-warn">{estado.texto}</p>}
      {estado.tipo === "sugestao" && (
        <div className="rounded-xl border-2 border-info bg-info-soft p-3 text-ink">
          <p className="text-sm font-bold">Rascunho gerado por IA — revise antes de usar</p>
          <p className="mt-1">{estado.texto}</p>
          {estado.pontos.length > 0 && (
            <ul className="mt-2 list-inside list-disc text-sm">
              {estado.pontos.map((p) => (
                <li key={p}>Conferir: {p}</li>
              ))}
            </ul>
          )}
          <div className="mt-2 flex gap-3">
            <button
              type="button"
              className="min-h-11 rounded-lg bg-primary px-3 text-sm font-bold text-primary-ink"
              onClick={() => {
                onAceitar(estado.texto);
                setEstado({ tipo: "parado" });
              }}
            >
              Usar este texto
            </button>
            <button type="button" className="min-h-11 rounded-lg px-3 text-sm font-semibold underline" onClick={() => setEstado({ tipo: "parado" })}>
              Descartar
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

