"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";
import { Aviso, Botao } from "@/components/ui";
import { solicitarAjudaAcao } from "../../acoes";

type Pedido = { id: string; tipo: string; descricao: string; criadoEm: string; resolvidaEm: string | null; resolucao: string | null };

const ROTULO: Record<string, string> = {
  dificuldade_medicamento: "Dificuldade para conseguir remédio",
  duvida_geral: "Dúvida",
  duvida_dose: "Dúvida sobre uma dose",
};

export function PedidoAjuda({ planoId, pedidos, telefone }: { planoId: string; pedidos: Pedido[]; telefone: string }) {
  const router = useRouter();
  const [tipo, setTipo] = useState<"duvida_geral" | "dificuldade_medicamento">("duvida_geral");
  const [texto, setTexto] = useState("");
  const [msg, setMsg] = useState<{ tom: "info" | "danger"; texto: string } | null>(null);

  async function enviar(e: FormEvent) {
    e.preventDefault();
    const r = await solicitarAjudaAcao({ planoId, tipo, texto });
    if (!r.ok) return setMsg({ tom: "danger", texto: r.erro });
    setTexto("");
    setMsg({ tom: "info", texto: "Enviado. A equipe responde em horário comercial (simulação)." });
    router.refresh();
  }

  return (
    <section id="pedidos" aria-labelledby="pedidos-titulo" className="space-y-4">
      <h2 id="pedidos-titulo" className="text-2xl font-extrabold">
        Precisa de algo que não é urgente?
      </h2>
      <p className="rounded-xl border-2 border-warn bg-warn-soft p-4 font-semibold text-ink">
        Este espaço não é acompanhado em tempo real. Para piora ou sinais de urgência, siga “Quando procurar ajuda”, ligue{" "}
        {telefone} ou 192.
      </p>
      <form onSubmit={enviar} className="space-y-3 rounded-2xl border border-line bg-surface p-5">
        <fieldset>
          <legend className="font-bold">Sobre o quê?</legend>
          <div className="mt-2 flex flex-wrap gap-4">
            <label className="flex min-h-11 items-center gap-2">
              <input type="radio" name="tipo" checked={tipo === "duvida_geral"} onChange={() => setTipo("duvida_geral")} /> Uma dúvida
            </label>
            <label className="flex min-h-11 items-center gap-2">
              <input type="radio" name="tipo" checked={tipo === "dificuldade_medicamento"} onChange={() => setTipo("dificuldade_medicamento")} /> Não consigo um remédio
            </label>
          </div>
        </fieldset>
        <label htmlFor="pedido-texto" className="block font-bold">
          Conte em poucas palavras
        </label>
        <textarea id="pedido-texto" rows={3} maxLength={300} value={texto} onChange={(e) => setTexto(e.target.value)} className="w-full rounded-xl border-2 border-line bg-surface p-3" />
        {msg && <Aviso tom={msg.tom}>{msg.texto}</Aviso>}
        <Botao type="submit" disabled={texto.trim().length < 3}>
          Enviar para a equipe
        </Botao>
      </form>
      {pedidos.length > 0 && (
        <ul className="space-y-2">
          {pedidos.map((p) => (
            <li key={p.id} className="rounded-xl border border-line bg-surface p-4">
              <p className="text-sm font-bold text-muted">
                {ROTULO[p.tipo] ?? p.tipo} · {new Date(p.criadoEm).toLocaleDateString("pt-BR")} ·{" "}
                {p.resolvidaEm ? <span className="text-primary">Respondido</span> : "Aguardando a equipe"}
              </p>
              <p className="mt-1">{p.descricao}</p>
              {p.resolucao && <p className="mt-2 rounded-lg bg-primary-soft p-2">Resposta da equipe: {p.resolucao}</p>}
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

import { eq } from "drizzle-orm";
import { NextResponse } from "next/server";
import { auditar } from "@/server/auditoria";
import { obterSessao } from "@/server/auth/sessao";
import { ehProfissional } from "@/server/authz/politicas";
import { db } from "@/server/db/cliente";
import { atendimento, paciente } from "@/server/db/schema";
import { conteudoPlanoSchema } from "@/server/dominio/conteudo";
import { lerPlanoParaEquipe } from "@/server/dominio/planos";
import { planoParaFhir } from "@/server/integracoes/fhir";

/** Exportação FHIR R4 de exemplo (sandbox). Leitura: não altera estado. */
export async function GET(_request: Request, ctx: RouteContext<"/equipe/planos/[id]/fhir">) {
  const naoEncontrado = () => NextResponse.json({ erro: "não encontrado" }, { status: 404, headers: { "Cache-Control": "no-store" } });
  const s = await obterSessao();
  if ("motivo" in s || !ehProfissional(s.ator) || !s.ator.mfaAtivo) return naoEncontrado();
  const { id } = await ctx.params;
  if (!/^[0-9a-f-]{36}$/.test(id)) return naoEncontrado();
  const dados = await lerPlanoParaEquipe(s.ator, id);
  if (!dados || dados.plano.status !== "publicado") return naoEncontrado();

  const [pac] = await db.select().from(paciente).where(eq(paciente.id, dados.plano.pacienteId));
  const [at] = await db.select().from(atendimento).where(eq(atendimento.id, dados.plano.atendimentoId));
  const bundle = planoParaFhir({
    planoId: dados.plano.id,
    versao: dados.plano.versao,
    publicadoEm: dados.plano.publicadoEm,
    paciente: { id: pac.id, nome: pac.nome, nascimento: pac.dataNascimento, prontuario: pac.prontuario },
    atendimento: { id: at.id, procedimento: at.procedimento, admissaoEm: at.admissaoEm },
    instituicao: dados.instituicao,
    conteudo: conteudoPlanoSchema.parse(dados.plano.conteudo),
  });
  await auditar({ atorUserId: s.ator.userId, instituicaoId: dados.plano.instituicaoId, acao: "plano.exportar_fhir", recursoTipo: "plano", recursoId: id, resultado: "permitido" });
  return new NextResponse(JSON.stringify(bundle, null, 2), {
    headers: {
      "Content-Type": "application/fhir+json; charset=utf-8",
      "Content-Disposition": `attachment; filename="alta-clara-plano-v${dados.plano.versao}-fhir-r4-sandbox.json"`,
      "Cache-Control": "no-store",
    },
  });
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Marca } from "@/components/Marca";
import { exigirSessao } from "@/server/auth/sessao";
import { lerQuestionario } from "@/server/dominio/entendimento";
import { Questionario } from "./Questionario";

export const metadata: Metadata = { title: "Confirme que entendeu", robots: { index: false, follow: false } };

export default async function Page(props: PageProps<"/paciente/planos/[id]/entendimento">) {
  const { ator } = await exigirSessao();
  const { id } = await props.params;
  if (!/^[0-9a-f-]{36}$/.test(id)) notFound();
  const q = await lerQuestionario(ator, id);
  if (!q) notFound();

  return (
    <main className="mx-auto w-full max-w-xl flex-1 px-4 py-6">
      <div className="flex items-center justify-between gap-3">
        <Marca href="/paciente" compacta />
        <Link href={`/paciente/planos/${id}`} className="min-h-11 content-center font-semibold text-primary underline">
          Voltar ao plano
        </Link>
      </div>
      <h1 className="mt-8 text-3xl font-extrabold">Confirme que entendeu</h1>
      <p className="mt-2 text-muted">
        Não é uma prova. As perguntas usam as orientações do seu próprio plano. Se algo ficar confuso, a equipe recebe um
        aviso para reforçar com você.
      </p>
      {q.perguntas.length === 0 ? (
        <p className="mt-6 rounded-2xl border border-line bg-surface p-5">Este plano ainda não tem perguntas de confirmação.</p>
      ) : (
        <Questionario planoId={id} perguntas={q.perguntas} />
      )}
    </main>
  );
}

"use client";

import Link from "next/link";
import { useState, type FormEvent } from "react";
import { Aviso, Botao } from "@/components/ui";
import { responderEntendimentoAcao } from "../../../acoes";

type Pergunta = { id: string; enunciado: string; opcoes: { id: string; texto: string }[]; secao: string };
type Resultado = { acertos: number; total: number; resultado: { id: string; enunciado: string; secao: string; correta: boolean; respostaCerta: string }[] };

const SECAO = { remedios: "Seus remédios", ajuda: "Quando procurar ajuda" } as Record<string, string>;

/** Uma pergunta por vez (modo de simplicidade), com resposta corrigida no servidor. */
export function Questionario({ planoId, perguntas }: { planoId: string; perguntas: Pergunta[] }) {
  const [indice, setIndice] = useState(0);
  const [respostas, setRespostas] = useState<Record<string, string>>({});
  const [resultado, setResultado] = useState<Resultado | null>(null);
  const [erro, setErro] = useState(false);
  const atual = perguntas[indice];

  async function avancar(e: FormEvent) {
    e.preventDefault();
    if (indice < perguntas.length - 1) return setIndice(indice + 1);
    const r = await responderEntendimentoAcao(planoId, respostas);
    if (!r.ok) return setErro(true);
    setResultado(r);
  }

  if (resultado) {
    return (
      <div className="mt-6 space-y-4" role="status">
        <p className="text-xl font-bold">
          Você respondeu {resultado.total} perguntas. {resultado.acertos === resultado.total ? "Tudo de acordo com o plano." : "Alguns pontos merecem reforço."}
        </p>
        <ul className="space-y-3">
          {resultado.resultado.map((r) => (
            <li key={r.id} className={`rounded-2xl border-2 p-4 ${r.correta ? "border-primary bg-primary-soft" : "border-warn bg-warn-soft"}`}>
              <p className="font-semibold text-ink">{r.enunciado}</p>
              <p className="mt-1 text-ink">
                {r.correta ? "De acordo com o plano." : "Segundo o seu plano:"} <strong>{r.respostaCerta}</strong>
              </p>
              {!r.correta && <p className="mt-1 text-sm text-ink">Veja em “{SECAO[r.secao]}”. A equipe foi avisada para reforçar este ponto com você.</p>}
            </li>
          ))}
        </ul>
        <p className="text-muted">Acertar estas perguntas não substitui conversar com a equipe sempre que tiver dúvida.</p>
        <Link href={`/paciente/planos/${planoId}`} className="inline-block font-semibold text-primary underline">
          Voltar ao plano
        </Link>
      </div>
    );
  }

  return (
    <form onSubmit={avancar} className="mt-6 space-y-5">
      <p className="text-sm font-bold text-muted" aria-live="polite">
        Pergunta {indice + 1} de {perguntas.length}
      </p>
      <fieldset key={atual.id}>
        <legend className="text-xl font-bold">{atual.enunciado}</legend>
        <div className="mt-4 space-y-2">
          {atual.opcoes.map((o) => (
            <label key={o.id} className="flex min-h-14 cursor-pointer items-center gap-3 rounded-xl border-2 border-line bg-surface px-4 has-checked:border-primary has-checked:bg-primary-soft">
              <input
                type="radio"
                name={atual.id}
                value={o.id}
                checked={respostas[atual.id] === o.id}
                onChange={() => setRespostas({ ...respostas, [atual.id]: o.id })}
                className="size-5"
              />
              <span className="text-lg">{o.texto}</span>
            </label>
          ))}
        </div>
      </fieldset>
      {erro && <Aviso tom="danger">Não foi possível enviar. Tente de novo.</Aviso>}
      <div className="flex gap-3">
        {indice > 0 && (
          <Botao variante="secundario" onClick={() => setIndice(indice - 1)}>
            Voltar
          </Botao>
        )}
        <Botao type="submit" disabled={!respostas[atual.id]}>
          {indice < perguntas.length - 1 ? "Próxima" : "Ver resultado"}
        </Botao>
      </div>
    </form>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Marca } from "@/components/Marca";
import { exigirSessao } from "@/server/auth/sessao";
import { historicoDoPlano } from "@/server/dominio/diferencas";

export const metadata: Metadata = { title: "O que mudou na minha alta", robots: { index: false, follow: false } };

const COR = { incluido: "border-primary", removido: "border-danger", alterado: "border-info" } as const;
const ROTULO = { incluido: "Incluído", removido: "Retirado", alterado: "Alterado" } as const;

export default async function Page(props: PageProps<"/paciente/planos/[id]/mudancas">) {
  const { ator } = await exigirSessao();
  const { id } = await props.params;
  if (!/^[0-9a-f-]{36}$/.test(id)) notFound();
  const historico = await historicoDoPlano(ator, id);
  if (!historico) notFound();

  return (
    <main className="mx-auto w-full max-w-xl flex-1 px-4 py-6">
      <div className="flex items-center justify-between gap-3">
        <Marca href="/paciente" compacta />
        <Link href={`/paciente/planos/${id}`} className="min-h-11 content-center font-semibold text-primary underline">
          Voltar ao plano
        </Link>
      </div>
      <h1 className="mt-8 text-3xl font-extrabold">O que mudou na minha alta?</h1>
      <p className="mt-2 text-muted">Cada versão foi revisada pela equipe antes de chegar até você. A mais recente vale a partir da data de publicação.</p>

      <ol className="mt-6 space-y-6">
        {[...historico].reverse().map((v) => (
          <li key={v.versao} className="rounded-2xl border border-line bg-surface p-5">
            <p className="text-sm font-bold uppercase tracking-wide text-primary">
              Versão {v.versao} {v.atual && "· atual"}
            </p>
            <p className="mt-1 text-muted">
              {v.publicadoEm && `Publicada em ${v.publicadoEm.toLocaleString("pt-BR", { dateStyle: "short", timeStyle: "short" })}. `}
              Preparada por {v.autor}
              {v.revisor && `, revisada por ${v.revisor}`}.
            </p>
            {v.motivo && <p className="mt-2 rounded-lg bg-bg p-2">Motivo informado pela equipe: {v.motivo}</p>}
            {v.mudancas === null ? (
              <p className="mt-3">Primeira versão das suas orientações.</p>
            ) : v.mudancas.length === 0 ? (
              <p className="mt-3">Sem diferenças no conteúdo em relação à versão anterior.</p>
            ) : (
              <ul className="mt-3 space-y-3">
                {v.mudancas.map((m, i) => (
                  <li key={i} className={`border-l-4 pl-3 ${COR[m.tipo]}`}>
                    <p className="text-sm font-bold text-muted">
                      {m.secao} · {ROTULO[m.tipo]}
                    </p>
                    <p className="font-semibold">{m.titulo}</p>
                    {m.antes && <p className="text-muted line-through decoration-1">Antes: {m.antes}</p>}
                    {m.depois && <p>Agora: {m.depois}</p>}
                  </li>
                ))}
              </ul>
            )}
          </li>
        ))}
      </ol>
    </main>
  );
}
